sys_script_include.script:
var InviteAjaxService = Class.create();
InviteAjaxService.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /**
     * Wird vom Modal aufgerufen wenn jemand eingeladen werden soll
     */
    sendInvitation: function() {
        var antragSysId = this.getParameter('sysparm_antrag');
        var antragTable = this.getParameter('sysparm_table');
        var email       = this.getParameter('sysparm_email');
        var currentUser = gs.getUserID();

        // Eingaben prüfen
        if (!antragSysId || !email) {
            return JSON.stringify({
                success: false,
                message: 'Fehlende Pflichtfelder.'
            });
        }

        // E-Mail Format prüfen (serverseitig nochmal!)
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            return JSON.stringify({
                success: false,
                message: 'Ungültige E-Mail-Adresse.'
            });
        }

        // InviteService aufrufen
        var inviteSvc = new InviteService();
        var result    = inviteSvc.createInvitation({
            recordTable: antragTable,
            recordId:    antragSysId,
            email:       email,
            role:        'admin',
            invitedBy:   currentUser,
            context:     'demo_request'
        });

        return JSON.stringify(result);
    },

    /**
     * Zugriff entziehen – wird von der Related List aufgerufen
     */
    revokeAccess: function() {
        var accessSysId = this.getParameter('sysparm_access_id');
        var currentUser = gs.getUserID();

        if (!accessSysId) {
            return JSON.stringify({
                success: false,
                message: 'Kein Zugriffseintrag angegeben.'
            });
        }

        var inviteSvc = new InviteService();
        var result    = inviteSvc.revokeAccess(accessSysId, currentUser);

        return JSON.stringify(result);
    },

    type: 'InviteAjaxService'
});
